INSERT INTO `tbl_workshop_data` (`id`, `name_arabic`, `name_english`, `address_arabic`, `address_english`, `other_arabic`, `other_english`, `phone`, `phone2`, `logo`, `footer`) VALUES
(1, 'مركز ار بي ام ون لصيانة السيارات', 'RPM For cars Maintenance', 'مكة المكرمة - شارع الحج - مقابل القصر الابيض للافراح', 'Makkah - AlHajj street - front of white hall', '', '', '0547101826', '0564993725', '1768166664.png', 'رقم حساب الورشة في بنك الانماء / SA9705000068202985683000 ورشة احمد سعيد باسنبل للميكانيكا والكهرباء');
INSERT INTO `terms` (`id`, `details`) VALUES
(1, 'يسمح للمهندس بقيادة السيارة خارج الورشة وذلك للتجربة.'),
(2, 'الورشة ليست مسئولة عن فقدان الأشياء الثمينة من السيارة ( نقود , ساعة , جوال , نظارة , أوراق هامة , غيرها ... ).'),
(3, 'في حالة تأمين الورشة للقطع فـإن نسبة الخصم 15% من سعر الشركة وليس للعميل الحق في الاعتراض عند الموافقة مسبقاً.'),
(4, 'في حالة فك المكينة فإن الورشة ليست مسئولة عن الجربكس الأوتوماتيك.'),
(5, 'في حال فك وتركيب راس المكينة , فالورشة غير مسؤولة عن المكينة اذا خبطت أو صلبت .وتبقى المسؤولية على العميل.'),
(6, 'في حال تغيير زيت الجربكس فالورشة غير مسؤولة عن خراب الجربكس , وتبقى المسؤولية على العميل.'),
(7, 'في حالة طلب العميل لسحب السيارة بعد الفك عليه دفع نصف المبلغ المتفق عليه مسبقاً وخاصة في حالة التوضيب أو فك الرأس.'),
(8, 'في حال تأخر العميل في احضار قطع الغيار فللورشة الأحقية في احضار قطع الغيار واكمال العمل دون الرجوع للعميل وعلى العميل دفع قيمة الفاتورة.'),
(9, 'في حال كسر أي قطعة أثناء العمل فإن الورشة غير مسؤولة عنها وعلى العميل احضار قطعة بديلة.'),
(10, 'في حال تأخر العميل عن استلام السيارة بعد صيانتها بسبعة أيام سيتم ايقاف السيارة خارج الورشة , والورشة غير مسؤولة عنها.'),
(11, 'لا يحق للعميل المجادلة عند الحساب طالما تم الاتفاق على الأجرة مسبقاً .'),
(12, 'في حالة تغيير ثلاجة المكيف فإن الورشة غير مسئولة عن كمبروسر المكيف .'),
(13, 'لا تسلم السيارة للعميل إلا بعد تسديد قيمة الفاتورة .'),
(15, 'عند سحب واعادة تعبئة الفريون بالجهاز ، فالورشة ليست مسؤولة عن ضرر الكمبروسر');
